import axios from "axios";
import { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { addToCart } from "../Redux/Slice";
import "../style/product.css";

export default function Products() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [error, setError] = useState("");

  const dispatch = useDispatch();
  const navigate = useNavigate();

  const cartItems = useSelector((state) => state.cart.items);

  // =========================
  // FETCH PRODUCTS
  // =========================

  const fetchProducts = async () => {
    try {
      setLoading(true);
      setError("");

      const token = localStorage.getItem("token");

      const response = await axios.get(
        "http://localhost:5000/api/v1/products",
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      setProducts(response.data.data || []);
    } catch (err) {
      console.error(err.response?.data || err.message);

      setError(
        err.response?.data?.message ||
          "Unable to load products. Please try again."
      );
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProducts();
  }, []);

  // =========================
  // SEARCH
  // =========================

  const filteredProducts = useMemo(() => {
    const keyword = search.trim().toLowerCase();

    if (!keyword) {
      return products;
    }

    return products.filter((product) =>
      product.name?.toLowerCase().includes(keyword)
    );
  }, [products, search]);

  // =========================
  // STOCK
  // =========================

  const getStock = (product) => {
    return Number(product.quantity ?? product.stock ?? 0);
  };

  const inStock = products.filter(
    (product) => getStock(product) > 10
  ).length;

  const lowStock = products.filter((product) => {
    const stock = getStock(product);
    return stock > 0 && stock <= 10;
  }).length;

  const outOfStock = products.filter(
    (product) => getStock(product) <= 0
  ).length;

  // =========================
  // STOCK BADGE
  // =========================

  const getStockStatus = (stock) => {
    if (stock <= 0) {
      return {
        text: "Out of Stock",
        className: "stock-badge stock-out",
      };
    }

    if (stock <= 10) {
      return {
        text: "Low Stock",
        className: "stock-badge stock-low",
      };
    }

    return {
      text: "In Stock",
      className: "stock-badge stock-good",
    };
  };

  // =========================
  // ADD TO CART
  // =========================

  const handleAddToCart = (product) => {
    dispatch(addToCart(product));
  };

  // =========================
  // RENDER
  // =========================

  return (
    <div className="products-page">

      {/* =========================
          PAGE HEADER
      ========================= */}

      <div className="products-header">

        <div>
          <div className="products-label">
            STORE CATALOG
          </div>

          <h1 className="products-title">
            Products
          </h1>

          <p className="products-subtitle">
            Manage your products, pricing and inventory.
          </p>
        </div>

        <button
          className="add-product-button"
          onClick={() => navigate("/add-product")}
        >
          <span>+</span>
          Add Product
        </button>

      </div>

      {/* =========================
          STATISTICS
      ========================= */}

      <div className="products-stats">

        <div className="stat-card">
          <div className="stat-icon total-icon">
            📦
          </div>

          <div>
            <span>Total Products</span>
            <strong>{products.length}</strong>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-icon success-icon">
            ✓
          </div>

          <div>
            <span>In Stock</span>
            <strong>{inStock}</strong>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-icon warning-icon">
            !
          </div>

          <div>
            <span>Low Stock</span>
            <strong>{lowStock}</strong>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-icon danger-icon">
            ×
          </div>

          <div>
            <span>Out of Stock</span>
            <strong>{outOfStock}</strong>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-icon cart-icon">
            🛒
          </div>

          <div>
            <span>Cart Items</span>
            <strong>{cartItems.length}</strong>
          </div>
        </div>

      </div>

      {/* =========================
          SEARCH TOOLBAR
      ========================= */}

      {!loading && !error && (
        <div className="products-toolbar">

          <div className="search-box">

            <span className="search-icon">
              🔍
            </span>

            <input
              type="text"
              placeholder="Search products by name..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />

            {search && (
              <button
                className="clear-search"
                onClick={() => setSearch("")}
              >
                ×
              </button>
            )}

          </div>

          <div className="showing-count">
            Showing{" "}
            <strong>{filteredProducts.length}</strong>{" "}
            of{" "}
            <strong>{products.length}</strong>{" "}
            products
          </div>

        </div>
      )}

      {/* =========================
          LOADING
      ========================= */}

      {loading && (
        <div className="products-loading">

          <div className="loading-spinner"></div>

          <h3>Loading products...</h3>

          <p>Please wait while we load your catalog.</p>

        </div>
      )}

      {/* =========================
          ERROR
      ========================= */}

      {!loading && error && (
        <div className="products-error">

          <div className="error-icon">
            !
          </div>

          <h3>Unable to load products</h3>

          <p>{error}</p>

          <button
            className="retry-button"
            onClick={fetchProducts}
          >
            Try Again
          </button>

        </div>
      )}

      {/* =========================
          EMPTY DATABASE
      ========================= */}

      {!loading &&
        !error &&
        products.length === 0 && (
          <div className="products-empty">

            <div className="empty-icon">
              📦
            </div>

            <h3>No Products Yet</h3>

            <p>
              Your product catalog is empty.
              Add your first product to get started.
            </p>

            <button
              className="add-product-button"
              onClick={() => navigate("/add-product")}
            >
              + Add Product
            </button>

          </div>
        )}

      {/* =========================
          PRODUCT TABLE
      ========================= */}

      {!loading &&
        !error &&
        products.length > 0 && (

          <div className="products-table-wrapper">

            {filteredProducts.length > 0 ? (

              <table className="products-table">

                <thead>
                  <tr>
                    <th>PRODUCT</th>
                    <th>PRICE</th>
                    <th>STOCK</th>
                    <th>STATUS</th>
                    <th>ACTION</th>
                  </tr>
                </thead>

                <tbody>

                  {filteredProducts.map((product) => {

                    const stock = getStock(product);

                    const stockStatus =
                      getStockStatus(stock);

                    const isInCart = cartItems.some(
                      (cartItem) =>
                        cartItem.id === product.id
                    );

                    return (
                      <tr key={product.id}>

                        {/* PRODUCT */}

                        <td>
                          <div className="product-info-cell">

                            <div className="product-thumbnail">

                              <img
                                src={
                                  product.image ||
                                  "https://via.placeholder.com/100?text=No+Image"
                                }
                                alt={
                                  product.name ||
                                  "Product"
                                }
                              />

                            </div>

                            <div className="product-details">

                              <h4>
                                {product.name ||
                                  "Unnamed Product"}
                              </h4>

                              <span>
                                ID #{product.id}
                              </span>

                            </div>

                          </div>
                        </td>

                        {/* PRICE */}

                        <td>
                          <span className="table-price">
                            ₹
                            {Number(
                              product.price || 0
                            ).toLocaleString("en-IN")}
                          </span>
                        </td>

                        {/* STOCK */}

                        <td>
                          <span className="stock-number">
                            {stock > 0
                              ? `${stock} units`
                              : "0 units"}
                          </span>
                        </td>

                        {/* STATUS */}

                        <td>
                          <span
                            className={
                              stockStatus.className
                            }
                          >
                            <span className="status-dot">
                              ●
                            </span>

                            {stockStatus.text}
                          </span>
                        </td>

                        {/* ACTION */}

                        <td>

                          <button
                            className={`table-cart-button ${
                              isInCart
                                ? "added"
                                : ""
                            }`}
                            disabled={
                              isInCart || stock <= 0
                            }
                            onClick={() =>
                              handleAddToCart(product)
                            }
                          >
                            {isInCart
                              ? "✓ Added"
                              : stock <= 0
                              ? "Unavailable"
                              : "Add to Cart"}
                          </button>

                        </td>

                      </tr>
                    );
                  })}

                </tbody>

              </table>

            ) : (

              <div className="no-results">

                <div className="no-results-icon">
                  🔍
                </div>

                <h3>No Products Found</h3>

                <p>
                  We couldn't find any product matching
                  "{search}".
                </p>

                <button
                  onClick={() => setSearch("")}
                >
                  Clear Search
                </button>

              </div>

            )}

          </div>
        )}

    </div>
  );
}
